import os
import google.cloud.documentai_v1 as documentai

def extract_receipt_fields(payload, config=None):
    config = config or {}
    project_id = os.environ.get("GOOGLE_CLOUD_PROJECT")
    location = "us"  # Or your preferred region, e.g., "eu"
    processor_id = config.get("processor_id", "CHANGE_TO_YOUR_RECEIPT_PROCESSOR_ID") # e.g., "your-receipt-parser-processor-id"

    # Create a client
    client = documentai.DocumentProcessorServiceClient()

    # The full resource name of the processor
    # e.g.: projects/project_id/locations/location/processors/processor_id
    name = client.processor_path(project_id, location, processor_id)

    # Read the file into memory
    document = documentai.RawDocument(
        content=payload,
        mime_type="application/pdf"  # Adjust if your payload is an image, e.g., "image/jpeg"
    )

    # Configure the process request
    request = documentai.ProcessRequest(name=name, raw_document=document)

    # Process the document
    result = client.process_document(request=request)

    extracted_data = {
        "merchant_name": None,
        "tax_amount": None,
        "total_amount": None,
        "items": []
    }

    if result.document:
        for entity in result.document.entities:
            if entity.type == "merchant_name" and entity.mention_text:
                extracted_data["merchant_name"] = entity.mention_text
            elif entity.type == "total_amount" and entity.mention_text:
                try:
                    extracted_data["total_amount"] = float(entity.mention_text)
                except ValueError:
                    extracted_data["total_amount"] = None
            elif entity.type == "tax_amount" and entity.mention_text:
                try:
                    extracted_data["tax_amount"] = float(entity.mention_text)
                except ValueError:
                    extracted_data["tax_amount"] = None
            elif entity.type == "line_item":
                item_data = {}
                for prop in entity.properties:
                    if prop.type == "description" and prop.mention_text:
                        item_data["description"] = prop.mention_text
                    elif prop.type == "amount" and prop.mention_text:
                        try:
                            item_data["amount"] = float(prop.mention_text)
                        except ValueError:
                            item_data["amount"] = None
                if item_data:
                    extracted_data["items"].append(item_data)
    return extracted_data
